function formatMessageTime(date) {
  return date.toLocaleTimeString("en-US", {
    hour: "numeric",
    minute: "2-digit",
  });
}

function formatRelativeTime(date) {
  const now = new Date();
  const diff = now - date;
  const minutes = Math.floor(diff / 60000);
  const hours = Math.floor(minutes / 60);

  if (minutes < 1) return "now";
  if (minutes < 60) return `${minutes}m`;
  if (hours < 24) return `${hours}h`;
  return date.toLocaleDateString("en-US", { month: "short", day: "numeric" });
}

function AdminChat() {
  const [conversations, setConversations] = useState(initialConversations);
  const [selectedChat, setSelectedChat] = useState(null);
  const [searchQuery, setSearchQuery] = useState("");
  const [filter, setFilter] = useState("all");
  const [messages, setMessages] = useState({});
  const [newMessage, setNewMessage] = useState("");
  const [showDetails, setShowDetails] = useState(false);
  const [showEmojiPicker, setShowEmojiPicker] = useState(false);
  const [uploadedImage, setUploadedImage] = useState(null);
  const [headerHover, setHeaderHover] = useState(false);
  const messagesEndRef = useRef(null);
  const currentAdminProfile = useState(() => {
    const stored = localStorage.getItem("massar_user_profile");
    return stored ? JSON.parse(stored) : null;
  });

  
  useEffect(() => {
    const fetchConversations = async () => {
      try {
        const data = await chatService.getConversations();
        if (data && data.length > 0) {
          
          setConversations((prev) =>
            prev.map((conv) => {
              const apiConv = data.find((c) => c.id === conv.id);
              if (apiConv) {
                return {
                  ...conv,
                  lastMessage: apiConv.last_message,
                  lastMessageTime: new Date(apiConv.last_message_time),
                  unread: apiConv.unread,
                };
              }
              return conv;
            }),
          );
        }
      } catch (err) {
        console.log("Using local chat data (API not available)");
      }
    };
    fetchConversations();
  }, []);

  
  useEffect(() => {
    if (selectedChat) {
      const fetchMessages = async () => {
        try {
          const data = await chatService.getMessages(selectedChat.id);
          if (data && data.length > 0) {
            const formatted = data.map((msg) => ({
              id: msg.id,
              sender: msg.sender,
              text: msg.text,
              image: msg.image,
              time: new Date(msg.time),
              isOwn: msg.sender === currentAdmin.name,
            }));
            setMessages((prev) => ({
              ...prev,
              [selectedChat.id]: formatted,
            }));
          } else if (!messages[selectedChat.id]) {
            
            setMessages((prev) => ({
              ...prev,
              [selectedChat.id]: mockMessages[selectedChat.id] || [],
            }));
          }
        } catch (err) {
          
          if (!messages[selectedChat.id]) {
            setMessages((prev) => ({
              ...prev,
              [selectedChat.id]: mockMessages[selectedChat.id] || [],
            }));
          }
        }
      };
      fetchMessages();
    }
  }, [selectedChat]);

  
  const filteredConversations = conversations.filter((conv) => {
    const matchesSearch = conv.name
      .toLowerCase()
      .includes(searchQuery.toLowerCase());
    if (filter === "unread") return matchesSearch && conv.unread > 0;
    if (filter === "read") return matchesSearch && conv.unread === 0;
    return matchesSearch;
  });

  
  const handleSelectChat = (conv) => {
    setSelectedChat(conv);
    setShowDetails(false);

    
    setConversations((prev) =>
      prev.map((c) => (c.id === conv.id ? { ...c, unread: 0 } : c)),
    );

    
    if (!messages[conv.id]) {
      setMessages((prev) => ({
        ...prev,
        [conv.id]: mockMessages[conv.id] || [],
      }));
    }
  };

  
  useEffect(() => {
    messagesEndRef.current?.scrollIntoView({ behavior: "smooth" });
  }, [messages, selectedChat]);

  
  const handleSendMessage = async () => {
    if (!newMessage.trim() && !uploadedImage) return;

    const newMsg = {
      id: Date.now(),
      sender: currentAdmin.name,
      text: newMessage,
      time: new Date(),
      isOwn: true,
      image: uploadedImage,
    };

    
    try {
      await chatService.sendMessage({
        conversationId: selectedChat.id,
        sender: currentAdmin.name,
        text: newMessage,
        image: uploadedImage,
      });
    } catch (err) {
      console.log("API not available, using local storage");
    }

    setMessages((prev) => ({
      ...prev,
      [selectedChat.id]: [...(prev[selectedChat.id] || []), newMsg],
    }));

    setNewMessage("");
    setUploadedImage(null);
  };

  // Handle key press
  const handleKeyPress = (e) => {
    if (e.key === "Enter" && !e.shiftKey) {
      e.preventDefault();
      handleSendMessage();
    }
  };

  
  const handleImageUpload = (e) => {
    const file = e.target.files[0];
    if (file) {
      const reader = new FileReader();
      reader.onloadend = () => {
        setUploadedImage(reader.result);
      };
      reader.readAsDataURL(file);
    }
  };

  
  const onlineCount = admins.filter((a) => a.status === "online").length;

  return (
    <div className={styles.page}>
      {}
      <div className={styles.sidebar}>
        <div className={styles.sidebarHeader}>
          <div className={styles.currentUser}>
            <div className={styles.avatar}>
              {currentAdminProfile?.[0]?.avatar ? (
                <img src={currentAdminProfile[0].avatar} alt="avatar" />
              ) : (
                <span className="material-symbols-outlined">
                  account_circle
                </span>
              )}
            </div>
            <div className={styles.userInfo}>
              <span className={styles.userName}>{currentAdmin.name}</span>
              <span className={styles.userRole}>{currentAdmin.role}</span>
            </div>
          </div>
        </div>

        <div className={styles.searchSection}>
          <div className={styles.searchBox}>
            <span className="material-symbols-outlined">search</span>
            <input
              type="text"
              placeholder="Search conversations..."
              value={searchQuery}
              onChange={(e) => setSearchQuery(e.target.value)}
            />
          </div>

          <div className={styles.filterTabs}>
            <button
              className={`${styles.filterTab} ${filter === "all" ? styles.filterActive : ""}`}
              onClick={() => setFilter("all")}
            >
              All
            </button>
            <button
              className={`${styles.filterTab} ${filter === "unread" ? styles.filterActive : ""}`}
              onClick={() => setFilter("unread")}
            >
              Unread
            </button>
            <button
              className={`${styles.filterTab} ${filter === "read" ? styles.filterActive : ""}`}
              onClick={() => setFilter("read")}
            >
              Read
            </button>
          </div>
        </div>

        <div className={styles.conversationList}>
          {filteredConversations.map((conv) => (
            <div
              key={conv.id}
              className={`${styles.conversationItem} ${selectedChat?.id === conv.id ? styles.conversationActive : ""}`}
              onClick={() => handleSelectChat(conv)}
            >
              <div className={styles.convAvatar}>
                {conv.type === "group" ? (
                  <div className={styles.groupAvatar}>
                    <span className="material-symbols-outlined">group</span>
                  </div>
                ) : (
                  <img src={conv.avatar} alt={conv.name} />
                )}
                {conv.unread > 0 && (
                  <span className={styles.unreadBadge}>{conv.unread}</span>
                )}
              </div>
              <div className={styles.convInfo}>
                <div className={styles.convHeader}>
                  <span className={styles.convName}>{conv.name}</span>
                  <span className={styles.convTime}>
                    {formatRelativeTime(conv.lastMessageTime)}
                  </span>
                </div>
                <p className={styles.convPreview}>{conv.lastMessage}</p>
              </div>
            </div>
          ))}
        </div>
      </div>

      {}
      <div className={styles.chatArea}>
        {selectedChat ? (
          <>
            <div
              className={styles.chatHeader}
              onMouseEnter={() => setHeaderHover(true)}
              onMouseLeave={() => setHeaderHover(false)}
            >
              <div className={styles.chatHeaderInfo}>
                {selectedChat.type === "group" ? (
                  <div className={styles.groupAvatar}>
                    <span className="material-symbols-outlined">group</span>
                  </div>
                ) : (
                  <div className={styles.avatar}>
                    <img src={selectedChat.avatar} alt={selectedChat.name} />
                  </div>
                )}
                <div>
                  <h3 className={styles.chatTitle}>{selectedChat.name}</h3>
                  {selectedChat.type === "group" ? (
                    <span className={styles.onlineCount}>
                      <span className={styles.memberCount}>
                        {admins.length} members ·{" "}
                      </span>
                      <span className={styles.onlineText}>
                        {onlineCount} online
                      </span>
                    </span>
                  ) : (
                    <span className={styles.chatStatus}>Online</span>
                  )}
                </div>
              </div>
              <button
                className={`${styles.detailsToggle} ${headerHover ? styles.iconHover : ""}`}
                onClick={() => setShowDetails(!showDetails)}
              >
                <span className="material-symbols-outlined">info</span>
              </button>
            </div>

            <div className={styles.messageList}>
              {(
                messages[selectedChat.id] ||
                mockMessages[selectedChat.id] ||
                []
              ).map((msg, index) => (
                <div
                  key={msg.id}
                  className={`${styles.message} ${msg.isOwn ? styles.messageOwn : ""}`}
                  style={{ animationDelay: `${index * 30}ms` }}
                >
                  {selectedChat.type === "group" && !msg.isOwn && (
                    <div className={styles.messageSenderInfo}>
                      <img
                        src={
                          ADMIN_AVATARS[msg.sender] ||
                          "https://i.pravatar.cc/150?u=default"
                        }
                        alt={msg.sender}
                        className={styles.senderAvatar}
                      />
                      <span className={styles.messageSender}>{msg.sender}</span>
                    </div>
                  )}
                  <div className={styles.messageBubble}>
                    {msg.image && (
                      <img
                        src={msg.image}
                        alt="attachment"
                        className={styles.messageImage}
                      />
                    )}
                    <p>{msg.text}</p>
                  </div>
                  <span className={styles.messageTime}>
                    {formatMessageTime(msg.time)}
                  </span>
                </div>
              ))}
              <div ref={messagesEndRef} />
            </div>

            <div className={styles.inputArea}>
              {uploadedImage && (
                <div className={styles.imagePreview}>
                  <img src={uploadedImage} alt="preview" />
                  <button onClick={() => setUploadedImage(null)}>
                    <span className="material-symbols-outlined">close</span>
                  </button>
                </div>
              )}
              <div className={styles.inputRow}>
                <button
                  className={`${styles.inputAction} ${headerHover ? styles.iconHover : ""}`}
                  onClick={() => setShowEmojiPicker(!showEmojiPicker)}
                >
                  <span className="material-symbols-outlined">
                    sentiment_satisfied
                  </span>
                </button>
                <label
                  className={`${styles.inputAction} ${headerHover ? styles.iconHover : ""}`}
                >
                  <span className="material-symbols-outlined">image</span>
                  <input
                    type="file"
                    accept="image/*"
                    onChange={handleImageUpload}
                    hidden
                  />
                </label>
                <textarea
                  className={styles.messageInput}
                  placeholder="Type a message..."
                  value={newMessage}
                  onChange={(e) => setNewMessage(e.target.value)}
                  onKeyDown={handleKeyPress}
                  rows={1}
                />
                <button className={styles.sendBtn} onClick={handleSendMessage}>
                  <span className="material-symbols-outlined">send</span>
                </button>
              </div>
            </div>
          </>
        ) : (
          <div className={styles.emptyState}>
            <div className={styles.emptyIcon}>
              <span className="material-symbols-outlined">chat_bubble</span>
            </div>
            <h3>Select a conversation</h3>
            <p>Choose a chat from the sidebar to start messaging</p>
          </div>
        )}
      </div>

      {}
      {selectedChat && (
        <div
          className={`${styles.detailsSidebar} ${showDetails ? styles.detailsVisible : ""}`}
        >
          <div className={styles.detailsContent}>
            {selectedChat.type === "group" ? (
              <>
                <div className={styles.detailsHeader}>
                  <div className={styles.groupAvatarLarge}>
                    <span className="material-symbols-outlined">group</span>
                  </div>
                  <h3>{selectedChat.name}</h3>
                  <span className={styles.memberCount}>
                    {admins.length} members · {onlineCount} online
                  </span>
                </div>

                <div className={styles.detailsSection}>
                  <h4>Members</h4>
                  {admins.map((admin) => (
                    <div key={admin.id} className={styles.memberItem}>
                      <div className={styles.avatar}>
                        <img src={ADMIN_AVATARS[admin.name]} alt={admin.name} />
                      </div>
                      <span>{admin.name}</span>
                      <span
                        className={`${styles.statusDot} ${styles[admin.status]}`}
                      ></span>
                    </div>
                  ))}
                </div>
              </>
            ) : (
              <>
                <div className={styles.detailsHeader}>
                  <div className={styles.avatarLarge}>
                    <img src={selectedChat.avatar} alt={selectedChat.name} />
                  </div>
                  <h3>{selectedChat.name}</h3>
                  <span className={styles.chatStatus}>Online</span>
                </div>

                <div className={styles.detailsSection}>
                  <h4>Shared Photos</h4>
                  <div className={styles.photoGrid}>
                    <div className={styles.photoThumb}></div>
                    <div className={styles.photoThumb}></div>
                    <div className={styles.photoThumb}></div>
                  </div>
                </div>

                <div className={styles.detailsSection}>
                  <h4>Shared Documents</h4>
                  <div className={styles.docItem}>
                    <span className="material-symbols-outlined">
                      description
                    </span>
                    <span>report_q4_2024.pdf</span>
                  </div>
                  <div className={styles.docItem}>
                    <span className="material-symbols-outlined">
                      description
                    </span>
                    <span>analytics_summary.docx</span>
                  </div>
                </div>
              </>
            )}
          </div>
        </div>
      )}
    </div>
  );
}

export default AdminChat;
